/bin/bash -c "python3 - <<'PY'
from pathlib import Path
names=['CSPS','AUL','AULA','CRR','CRRA','DeltaP','DeltaPA']
for page,model in [(19,'RoBERTa'),(20,'distilRoBERTa'),(21,'BERT'),(22,'distilBERT')]:
    lines=Path(f'tmp/pdfs/page-{page:02d}.txt').read_text().splitlines()
    condition=None
    entries=[]
    for line in lines:
        if 'Re-train Dataset' in line:
            if entries:
                print(model,condition,'n=',len(entries),'wrong-sign counts=',dict(zip(names,[sum(row[j]<50 if condition=='dis' else row[j]>50 for row in entries) for j in range(7)])),'ties=',dict(zip(names,[sum(row[j]==50 for row in entries) for j in range(7)])))
            condition='dis' if 'Sdis' in line else 'adv'
            entries=[]
        cols=line.replace('†','').split()
        if condition and cols and cols[0]"'!='"'AA':
            try:
                nums=[float(x) for x in cols[-7:]]
            except ValueError:
                continue
            if len(nums)==7:
                entries.append(nums)
    if entries:
        print(model,condition,'n=',len(entries),'wrong-sign counts=',dict(zip(names,[sum(row[j]<50 if condition=='dis' else row[j]>50 for row in entries) for j in range(7)])),'ties=',dict(zip(names,[sum(row[j]==50 for row in entries) for j in range(7)])))
PY"
